import{_ as r,a0 as a,w as s,s as i,ao as l,I as p,x as e,a1 as u,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux有問必答：如何刪除Ubuntu上不再使用的舊內核 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何刪除Ubuntu上不再使用的舊內核 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何刪除Ubuntu上不再使用的舊內核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何刪除Ubuntu上不再使用的舊內核 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150914 Linux FAQs with Answers--How to remove unused old kernel images on Ubuntu","title":"Linux有問必答：如何刪除Ubuntu上不再使用的舊內核","tag":"201509","desc":""},"relativePath":"201509/20150914 Linux FAQs with Answers--How to remove unused old kernel images on Ubuntu.md","filePath":"[post].md"}'),d={name:"201509/20150914 Linux FAQs with Answers--How to remove unused old kernel images on Ubuntu.md"};function m(g,t,x,b,f,U){const n=a("Link");return s(),i("div",null,[t[13]||(t[13]=l(`<h1 id="linux有問必答-如何刪除ubuntu上不再使用的舊內核" tabindex="-1">Linux有問必答：如何刪除Ubuntu上不再使用的舊內核 <a class="header-anchor" href="#linux有問必答-如何刪除ubuntu上不再使用的舊內核" aria-label="Permalink to “Linux有問必答：如何刪除Ubuntu上不再使用的舊內核”">​</a></h1><blockquote><p><strong>提問</strong>：過去我已經在我的Ubuntu上升級了幾次內核。現在我想要刪除這些舊的內核鏡像來節省我的磁盤空間。如何用最簡單的方法刪除Ubuntu上先前版本的內核？</p></blockquote><p>在Ubuntu上，有幾個方法來升級內核。在Ubuntu桌面中，軟件更新允許你每天檢查並更新到最新的內核上。在Ubuntu服務器上，最為重要的安全更新項目之一就是 unattended-upgrades 軟件包會自動更新內核。然而，你也可以手動用apt-get或者aptitude命令來更新。</p><p>隨着時間的流逝，持續的內核更新會在系統中積聚大量的不再使用的內核，浪費你的磁盤空間。每個內核鏡像和其相關聯的模組/頭文件會佔用200-400MB的磁盤空間，因此由不再使用的內核而浪費的磁盤空間會快速地增加。</p><p><img src="https://farm1.staticflickr.com/636/21352725115_29ae7aab5f_c.jpg" alt=""></p><p>GRUB管理器為每個舊內核都維護了一個GRUB入口，以備你想要使用它們。</p><p><img src="https://farm6.staticflickr.com/5803/21164866468_07760fc23c_z.jpg" alt=""></p><p>作為磁盤清理的一部分，如果你不再使用這些，你可以考慮清理掉這些鏡像。</p><h3 id="如何清理舊內核鏡像" tabindex="-1">如何清理舊內核鏡像 <a class="header-anchor" href="#如何清理舊內核鏡像" aria-label="Permalink to “如何清理舊內核鏡像”">​</a></h3><p>在刪除舊內核之前，記住最好留有2個最近的內核（最新的和上一個版本），以防主要的版本出錯。現在就讓我們看看如何在Ubuntu上清理舊內核。</p><p>在Ubuntu內核鏡像包含了以下的包。</p><ul><li><code>linux-image-&lt;VERSION-NUMBER&gt;</code>: 內核鏡像</li><li><code>linux-image-extra-&lt;VERSION-NUMBER&gt;</code>: 額外的內核模組</li><li><code>linux-headers-&lt;VERSION-NUMBER&gt;</code>: 內核頭文件</li></ul><p>首先檢查系統中安裝的內核鏡像。</p><pre><code>$ dpkg --list | grep linux-image
$ dpkg --list | grep linux-headers
</code></pre><p>在列出的內核鏡像中，你可以移除一個特定的版本（比如3.19.0-15）。</p><pre><code>$ sudo apt-get purge linux-image-3.19.0-15
$ sudo apt-get purge linux-headers-3.19.0-15
</code></pre><p>上面的命令會刪除內核鏡像和它相關聯的內核模組和頭文件。</p><p>注意如果你還沒有升級內核那麼刪除舊內核會自動觸發安裝新內核。這樣在刪除舊內核之後，GRUB配置會自動升級來移除GRUB菜單中相關GRUB入口。</p><p>如果你有很多沒用的內核，你可以用shell表達式來一次性地刪除多個內核。注意這個括號表達式只在bash或者兼容的shell中才有效。</p><pre><code>$ sudo apt-get purge linux-image-3.19.0-{18,20,21,25}
$ sudo apt-get purge linux-headers-3.19.0-{18,20,21,25}
</code></pre><p><img src="https://farm6.staticflickr.com/5619/21352725355_39cc4fc2d0_c.jpg" alt=""></p><p>上面的命令會刪除4個內核鏡像：3.19.0-18、3.19.0-20、3.19.0-21 和 3.19.0-25。</p><p>如果GRUB配置由於任何原因在刪除舊內核後沒有正確升級，你可以嘗試手動用update-grub2命令來更新配置。</p><pre><code>$ sudo update-grub2
</code></pre><p>現在就重啓來驗證GRUB菜單是否已經正確清理了。</p><p><img src="https://farm1.staticflickr.com/593/20731623163_cccfeac854_z.jpg" alt=""></p><hr>`,27)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://ask.xmodulo.com/remove-kernel-images-ubuntu.html"},{default:o(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/remove-kernel-images-ubuntu.html",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),u(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),u(n,{href:"https://github.com/geekpi"},{default:o(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),u(n,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const h=r(d,[["render",m]]);export{_ as __pageData,h as default};
